package com.digithon.hr.security;

import org.springframework.beans.factory.DisposableBean;
import org.springframework.stereotype.Component;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * Encrypted-read switch, generated by PI Co-Pilot. Polls the pi_feature_flag table that PI Co-Pilot's
 * "Enable Encryption" toggle writes. While "encrypted-read" is on, entities and native queries read PI values from the
 * encrypted columns and writes also fill them. While it is off the application behaves exactly as before.
 */
@Component
public class PiEncryptionFlags implements DisposableBean {

    public static final String ENCRYPTED_READ = "encrypted-read";
    private static final long REFRESH_SECONDS = 5;

    private static volatile boolean encryptedRead;

    private final DataSource dataSource;
    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
        Thread t = new Thread(r, "pi-encryption-flags");
        t.setDaemon(true);
        return t;
    });

    public PiEncryptionFlags(DataSource dataSource) {
        this.dataSource = dataSource;
        refresh();
        scheduler.scheduleWithFixedDelay(this::refresh, REFRESH_SECONDS, REFRESH_SECONDS, TimeUnit.SECONDS);
    }

    /** Read by PiEncryptionListener and PiNativeQueryRouter on every call. */
    public static boolean encryptedRead() {
        return encryptedRead;
    }

    void refresh() {
        try (Connection connection = dataSource.getConnection();
             PreparedStatement st = connection.prepareStatement(
                 "SELECT enabled FROM pi_feature_flag WHERE flag_name = ?")) {
            st.setString(1, ENCRYPTED_READ);
            try (ResultSet rs = st.executeQuery()) {
                encryptedRead = rs.next() && rs.getBoolean(1);
            }
        } catch (SQLException e) {
            // Table not created yet or database unavailable: keep the last known value
        }
    }

    @Override
    public void destroy() {
        scheduler.shutdownNow();
    }
}
